const events = $input.all().map(i => i.json).filter(e => e.id);

// --- STATS GLOBALES ---
const nb_events = events.length;
let nb_alertes = 0, total_score = 0, nb_score = 0;
const timestamps = [];
const par_camera = {};

for (const evt of events) {
  const cam = evt.camera || 'inconnue';
  if (!par_camera[cam]) par_camera[cam] = { nb: 0, alertes: 0, scores: [], derniere: null };
  par_camera[cam].nb++;
  if (evt.data?.max_severity === 'alert') { nb_alertes++; par_camera[cam].alertes++; }
  if (evt.data?.top_score) {
    total_score += evt.data.top_score * 100;
    nb_score++;
    par_camera[cam].scores.push(evt.data.top_score * 100);
  }
  if (evt.start_time) {
    timestamps.push(evt.start_time);
    if (!par_camera[cam].derniere || evt.start_time > par_camera[cam].derniere) par_camera[cam].derniere = evt.start_time;
  }
}

timestamps.sort();

const score_moyen = nb_score > 0 ? Math.round(total_score / nb_score) + '%' : '--';
const premiere_detection = timestamps.length > 0 ? new Date(timestamps[0] * 1000).toLocaleTimeString('fr-FR', {hour:'2-digit', minute:'2-digit'}) : '--';
const derniere_detection = timestamps.length > 0 ? new Date(timestamps[timestamps.length-1] * 1000).toLocaleTimeString('fr-FR', {hour:'2-digit', minute:'2-digit'}) : '--';
const maintenant = new Date().toLocaleTimeString('fr-FR', {hour:'2-digit', minute:'2-digit', second:'2-digit'});
const date_longue = new Date().toLocaleDateString('fr-FR', {weekday:'long', year:'numeric', month:'long', day:'numeric'});

// --- STATUT GLOBAL ---
const statut_global_html = nb_alertes > 0
  ? `<div class="status-banner alert"><div class="dot dot-alert"></div>${nb_alertes} alerte(s) active(s) — Intervention requise</div>`
  : `<div class="status-banner ok"><div class="dot dot-ok"></div>Toutes les caméras — RAS</div>`;

const alertes_sub = nb_alertes > 0 ? 'Intervention requise' : 'Aucune anomalie';
const alertes_gstat_class = nb_alertes > 0 ? 'alert' : 'ok';

// --- CAMERAS ROWS ---
const cameras_rows = Object.entries(par_camera).map(([cam, s]) => {
  const score_cam = s.scores.length > 0 ? Math.round(s.scores.reduce((a,b)=>a+b,0)/s.scores.length) + '%' : '--';
  const derniere_cam = s.derniere ? new Date(s.derniere * 1000).toLocaleTimeString('fr-FR', {hour:'2-digit', minute:'2-digit'}) : '--';
  const badge = s.alertes > 0
    ? `<span style="font-size:10px;font-weight:800;padding:3px 10px;border-radius:20px;background:#fdf0ef;color:#c0392b;letter-spacing:.3px;">⚠ ALERTE</span>`
    : `<span style="font-size:10px;font-weight:800;padding:3px 10px;border-radius:20px;background:#e6f5ec;color:#1a5c30;letter-spacing:.3px;">● RAS</span>`;
  return `<tr>
    <td style="font-weight:700;color:#111d15;">${cam}</td>
    <td style="color:#3a5a3e;">${s.nb}</td>
    <td>${badge}</td>
    <td style="color:#7a9b80;">${score_cam}</td>
    <td style="color:#7a9b80;">${derniere_cam}</td>
  </tr>`;
}).join('');

// --- TIMELINE ---
const tl = new Array(24).fill(0);
for (const ts of timestamps) tl[new Date(ts * 1000).getHours()]++;
const timeline_labels_json = JSON.stringify(Array.from({length:24}, (_,i) => i+'h'));
const timeline_data_json = JSON.stringify(tl);

// --- ALERTES ROWS ---
const alertes_events = events.filter(e => e.data?.max_severity === 'alert').slice(0, 10);
const alertes_rows = alertes_events.length === 0
  ? '<div class="empty-state">Aucune alerte dans les dernières 24h</div>'
  : alertes_events.map(evt => {
      const heure = new Date(evt.start_time * 1000).toLocaleTimeString('fr-FR', {hour:'2-digit', minute:'2-digit', second:'2-digit'});
      const score = Math.round((evt.data?.top_score || 0) * 100);
      const duree = evt.end_time ? Math.round(evt.end_time - evt.start_time) + 's' : 'en cours';
      return `<div class="alert-row">
        <div class="alert-time">${heure}</div>
        <div class="alert-cam">${evt.camera || 'inconnue'} · ${duree}</div>
        <div><span class="badge-alert">Alerte</span></div>
        <div class="alert-score">${score}%</div>
      </div>`;
    }).join('');

// --- SNAPSHOT ---
const dernier_evt = events.find(e => e.has_snapshot);
const snapshot_html = dernier_evt
  ? `<img class="snapshot-img" src="http://localhost:5000/api/events/${dernier_evt.id}/snapshot.jpg" alt="Snapshot">`
  : `<div class="snapshot-placeholder"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#7a9b80" stroke-width="1.5"><rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8M12 17v4"/></svg>Aucun snapshot</div>`;
const snapshot_cam = dernier_evt?.camera || '--';

// --- LECTURE + REMPLACEMENT ---
const fs = require('fs');
let html = fs.readFileSync('/home/belliard/.n8n/seniorassist-dashboard-v5.html', 'utf8');

html = html
  .replace('STATUT_GLOBAL_HTML', statut_global_html)
  .replace('MAINTENANT', maintenant)
  .replace('DATE_LONGUE', date_longue)
  .replace('ALERTES_GSTAT_CLASS', alertes_gstat_class)
  .replace('ALERTES_SUB', alertes_sub)
  .replace('ALERTES_ROWS', alertes_rows)
  .replace('SNAPSHOT_HTML', snapshot_html)
  .replace('CAMERAS_ROWS', cameras_rows)
  .replace('SNAPSHOT_CAM', snapshot_cam)
  .replace('TIMELINE_LABELS', timeline_labels_json)
  .replace('TIMELINE_DATA', timeline_data_json);

while (html.includes('NB_EVENTS')) html = html.replace('NB_EVENTS', nb_events);
while (html.includes('NB_ALERTES')) html = html.replace('NB_ALERTES', nb_alertes);
while (html.includes('PREMIERE_DETECTION')) html = html.replace('PREMIERE_DETECTION', premiere_detection);
while (html.includes('DERNIERE_DETECTION')) html = html.replace('DERNIERE_DETECTION', derniere_detection);
while (html.includes('SCORE_MOYEN')) html = html.replace('SCORE_MOYEN', score_moyen);

return [{ json: { html } }];
